<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../../api';const data=ref<any>({cards:[]});onMounted(async()=>data.value=(await api.get('/admin/dashboard')).data);</script><template><section class="page"><h1 class="page-title">运营概览</h1><div class="cards"><div v-for="card in data.cards" :key="card.label" class="card"><span>{{card.label}}</span><div class="metric">{{card.value}}</div></div></div><div class="card" style="margin-top:18px"><h3>近 7 日增长趋势</h3><el-progress v-for="(value,index) in data.trend" :key="index" :percentage="value" :format="()=>`${value}`"/></div></section></template>
